import { total } from './cart.js';

// The printed wholesale price list gives 5% off from 10 lines. The cart's own
// bulk threshold is lower, so the invoice states the price-list rule explicitly.
const PRICE_LIST_BULK_MIN_LINES = 10;

// Invoices for wholesale orders (#7). The amount due follows the printed price
// list that wholesale customers order from — list price below 10 lines, 5% off
// from 10 lines, half a yen rounded up.
export function invoice(customer, items) {
  return { customer, due: total(items, 0, { bulkMinLines: PRICE_LIST_BULK_MIN_LINES }) };
}
